export type PostWoocommerceWebhookData = {
  /**
   * Topic-specific WooCommerce product payload.
   * Every topic requires `id`. For `product.created` and `product.updated`, `status: publish` captures an UPSERT and requires nonblank `name` and `permalink`; `status: trash`, `draft`, `pending`, or `private` captures a DELETE and requires only `id`. Missing or unsupported create/update statuses are authorized ignored events and require only `id`. `product.deleted` captures a DELETE and requires only `id`; its other fields are optional and ignored when absent.
   * When present on an event that maps to raw capture, WooCommerce `date_modified_gmt` is the source ordering timestamp. It accepts a no-offset GMT value interpreted as UTC, RFC3339 `Z`, or RFC3339 `+00:00`; malformed or nonzero-offset values return `400 BAD_BODY_VALUE`. `product.created` and `product.updated` events with missing or unsupported status are ignored only after capability and source authorization, then acknowledge `204` without parsing `date_modified_gmt` or constructing a provider receipt; a denied ignored event returns `403 FORBIDDEN`. An authorized ignored event persists no provider receipt even if a delivery ID is supplied. Omit it when source order is unavailable; an omitted timestamp provides no source-ordering guarantee.
   *
   */
  body: WoocommerceProductWebhookUpsertData | WoocommerceProductWebhookDeleteData;
  headers: {
    /**
     * WooCommerce webhook topic that determines how the payload is interpreted.
     * Only the listed topic values are accepted.
     *
     */
    'x-wc-webhook-topic': 'product.created' | 'product.updated' | 'product.deleted';
    /**
     * Base64-encoded HMAC-SHA256 signature of the raw HTTP request body, calculated with the
     * listing source's configured `woocommerceWebhookSecret`.
     *
     */
    'x-wc-webhook-signature': string;
    /**
     * Optional WooCommerce delivery identifier. For an event that maps to raw capture, its receipt retains only a canonical semantic source-payload SHA-256 evidence digest for 90 days and deduplicates retries. Reusing the identifier with a different digest returns `409 WOOCOMMERCE_PROVIDER_RECEIPT_DIGEST_CONFLICT`. Logical receipt expiry permits a new receipt but never removes or rewrites a captured raw revision or its provenance. Authorized ignored create/update status events persist no receipt and receive no receipt-based retry-deduplication, even when this header is supplied. When absent, no provider receipt or receipt-based retry-deduplication guarantee is made.
     */
    'x-wc-webhook-delivery-id'?: string;
  };
  path: {
    /**
     * Unique identifier of the target ListingSource that should receive the WooCommerce webhook
     */
    listingSourceId: string;
  };
  query?: never;
  url: '/api/v1/webhooks/woocommerce/{listingSourceId}';
};

export type PostWoocommerceWebhookErrors = {
  /**
   * Bad request — invalid or missing listing source ID, missing body, malformed JSON, unsupported
   * WooCommerce topic, an invalid `date_modified_gmt` source timestamp (including a nonzero offset) for an event that maps to raw capture, or a missing field required by the selected capture operation.
   *
   */
  400: ApiError;
  /**
   * Unauthorized — missing or invalid bearer credentials use `INVALID_CREDENTIALS`. A missing or invalid
   * WooCommerce signature uses `BAD_HEADER_VALUE`.
   *
   */
  401: ApiError;
  /**
   * Forbidden — the caller lacks the required ProductListing write capability or exact source partnership grant, including for ignored status events
   */
  403: ApiError;
  /**
   * Not found — the specified listing source does not exist
   */
  404: ApiError;
  /**
   * Conflict — a delivery receipt conflicts with its retained evidence digest (`WOOCOMMERCE_PROVIDER_RECEIPT_DIGEST_CONFLICT`), distinct evidence has the same `date_modified_gmt` timestamp (`WOOCOMMERCE_PROVIDER_SOURCE_ORDER_CONFLICT`), or an UPSERT cannot safely cross a delete ordering boundary (`WOOCOMMERCE_PROVIDER_SOURCE_ORDER_AMBIGUOUS`).
   */
  409: ApiError;
  /**
   * Internal server error — this route emits only `AUTH_INTERNAL_ERROR`, `LISTING_SOURCE_INTERNAL_ERROR`, or `PRODUCT_LISTING_INTERNAL_ERROR`.
   */
  500: ApiError;
  /**
   * Service unavailable — this route emits only `AUTH_TEMPORARILY_UNAVAILABLE`, `LISTING_SOURCE_TEMPORARILY_UNAVAILABLE`, or `PRODUCT_LISTING_TEMPORARILY_UNAVAILABLE`.
   */
  503: ApiError;
};

export type PostWoocommerceWebhookError = PostWoocommerceWebhookErrors[keyof PostWoocommerceWebhookErrors];

export type PostWoocommerceWebhookResponses = {
  /**
   * Webhook capability, signature, and source authorization are validated. A `204` acknowledges an authorized ignored create/update event with missing or unsupported status, or a durably captured changed, unchanged, duplicate, or stale outcome; it does not mean a new raw revision was written. Ignored events do not parse `date_modified_gmt` or construct a provider receipt. A provider receipt exists only for an event that maps to raw capture and carries a delivery ID; authorized ignored events persist no receipt even when a delivery ID is supplied. Source ordering is evaluated only for an event that maps to raw capture with a valid `date_modified_gmt`. When a delivery ID or source timestamp is omitted, no corresponding receipt or source-ordering guarantee is made. Canonical ProductListing normalization runs asynchronously. The backend returns no response body on success.
   *
   */
  204: void;
};

export type PostWoocommerceWebhookResponse = PostWoocommerceWebhookResponses[keyof PostWoocommerceWebhookResponses];

